# 完整欄位順序（含 sku_no，僅作初次建檔建議編號用，比對時不採用）
COLUMNS = ['sku_no', 'continent', 'country', 'name', 'process', 'variety', 'flavor', 'rating', 'strategy', 'batch_hint', 'cost_range_raw', 'cost_ntd_100g_raw', 'retail_ntd_100g_raw', 'margin_pct_raw', 'notes', 'season', 'importer', 'shelf_life_months', 'is_active']

# 實際會被寫入/更新的商品描述欄位（不含 sku_no，因為 sku_no 由資料庫自然鍵比對後決定）
DATA_COLUMNS = ['continent', 'country', 'name', 'process', 'variety', 'flavor', 'rating', 'strategy', 'batch_hint', 'cost_range_raw', 'cost_ntd_100g_raw', 'retail_ntd_100g_raw', 'margin_pct_raw', 'notes', 'season', 'importer', 'shelf_life_months', 'is_active']

FIND_BY_NATURAL_KEY_SQL = text("""
SELECT sku_no FROM products WHERE continent = :continent AND country = :country AND name = :name
""")

MAX_SKU_SQL = text("SELECT COALESCE(MAX(sku_no), 0) FROM products")

INSERT_SQL = text("""
INSERT INTO products
(sku_no, continent, country, name, process, variety, flavor, rating, strategy,
batch_hint, cost_range_raw, cost_ntd_100g_raw, retail_ntd_100g_raw, margin_pct_raw,
notes, season, importer, shelf_life_months, is_active)
VALUES (:sku_no, :continent, :country, :name, :process, :variety, :flavor, :rating, :strategy,
:batch_hint, :cost_range_raw, :cost_ntd_100g_raw, :retail_ntd_100g_raw, :margin_pct_raw,
:notes, :season, :importer, :shelf_life_months, :is_active)
""")

UPDATE_SQL = text("""
UPDATE products SET
process = :process, variety = :variety, flavor = :flavor, rating = :rating,
strategy = :strategy, batch_hint = :batch_hint, cost_range_raw = :cost_range_raw,
cost_ntd_100g_raw = :cost_ntd_100g_raw, retail_ntd_100g_raw = :retail_ntd_100g_raw,
margin_pct_raw = :margin_pct_raw, notes = :notes, season = :season,
importer = :importer, shelf_life_months = :shelf_life_months, is_active = :is_active
WHERE sku_no = :sku_no
""")

def seed():
    """
    匯入135筆SKU商品主檔，改用自然鍵 (continent, country, name) 比對：
    - 自然鍵已存在 -> 僅更新描述欄位，保留資料庫原有 sku_no（不變動編號）
    - 自然鍵不存在（全新品項） -> 指派「目前最大sku_no + 1」的新編號並新增
    此設計確保無論未來新豆單插入 PRODUCTS 列表的哪個位置，
    既有品項在資料庫中的 sku_no 永遠不會被改動，
    從根本避免 batches/transactions 外鍵綁錯商品的「排序錯亂」風險。
    """
    init_db()
    with get_conn() as conn:
        next_sku = conn.execute(MAX_SKU_SQL).scalar() or 0
        for row in PRODUCTS:
            full_params = dict(zip(COLUMNS, row))
            natural_key = {
                "continent": full_params["continent"],
                "country": full_params["country"],
                "name": full_params["name"],
            }
            existing = conn.execute(FIND_BY_NATURAL_KEY_SQL, natural_key).mappings().first()
            if existing:
                update_params = dict(full_params)
                update_params["sku_no"] = existing["sku_no"]
                conn.execute(UPDATE_SQL, update_params)
            else:
                next_sku += 1
                insert_params = dict(full_params)
                insert_params["sku_no"] = next_sku
                conn.execute(INSERT_SQL, insert_params)
    print("Seed complete: " + str(len(PRODUCTS)) + " SKU entries processed "
          "(existing sku_no preserved; new items appended with next available number)")

if __name__ == "__main__":
    seed()
